import json

class AgroPulseSensorNode:
    def __init__(self, node_id, threshold_moisture=30.0):
        self.node_id = node_id
        self.threshold_moisture = threshold_moisture

    def read_soil_sensor(self):
        return 24.5  

    def evaluate_crop_health(self, moisture_level):
        if moisture_level < self.threshold_moisture:
            return {
                "status": "WARNING",
                "message": "Soil moisture critically low. Irrigation triggered.",
                "action_required": True
            }
        return {
            "status": "OPTIMAL",
            "message": "Soil moisture levels are within normal range.",
            "action_required": False
        }

    def run_monitoring_cycle(self):
        moisture = self.read_soil_sensor()
        assessment = self.evaluate_crop_health(moisture)

        telemetry_data = {
            "node_id": self.node_id,
            "timestamp": time.time(),
            "moisture_percentage": moisture,
            "assessment": assessment
        }

        return json.dumps(telemetry_data, indent=2)

