import numpy as np

class AnomalyDetector:
    def __init__(self, threshold=2.5):
        self.threshold = threshold

    def evaluate_traffic(self, packet_sizes):
        mean = np.mean(packet_sizes)
        std = np.std(packet_sizes)
        z_scores = (packet_sizes - mean) / (std + 1e-8)
        return np.where(np.abs(z_scores) > self.threshold, 1, 0)

